SourceCode.Declaration:
using Microsoft.Dynamics.Integration.Telemetry;

/// <summary>
/// Class used to log telemetry events to Application Insights in Azure
/// </summary>
public class SysGlobalTelemetry
{
}

Method.Source:
/// <summary>
/// Finds the application ID of the client.
/// </summary>
/// <returns>The application ID of the client.</returns>
public static str findAppId()
{
    return SysEnvironmentUtil::getLocationByAppName(SysIntParameters::Find().TelemetryAppName);
}

    /// <summary>
    /// Creates a new instance of the TelemetryClient class.
    /// </summary>
    /// <param name = "_appId">The application ID of the client.</param>
    /// <returns>The TelemetryClient instance.</returns>
    public static TelemetryClient newClient(str _appId)
    {
        TelemetryClient cli;
        str instanceName = '';
        str roleName = '';

        try
        {
            instanceName = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment().Infrastructure.HostedServiceName;
            roleName = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory::GetApplicationEnvironment().Common.HostingEnvironment.ToString();
        }
        catch
        {
            instanceName = 'NotFound';
            roleName = 'NotFound';
        }
        
        cli = new Microsoft.Dynamics.Integration.Telemetry.TelemetryClient(_appId, 
            curUserId(), 
            sessionId(), 
            BatchHeader::isExecutingInBatch(), 
            instanceName, 
            roleName,
            curExt(),
            BatchHeader::getCurrentBatchTask().BatchJobId);
        return cli;
    }

    /// <summary>
    /// Client details are instantiated outside of this framework as each implementation
    /// </summary>
    /// <param name = "_result">EventHandlerResult vehicle to marshal the object back to this package</param>
    static delegate void instantiateClient(EventHandlerResult _result)
    {

    }

/// <summary>
/// Logs errors to AppInsights.
/// </summary>
/// <param name="args">The arguments for the error method.</param>
[PreHandlerFor(classStr(Global), staticMethodStr(Global, error))]
public static void Global_Pre_error(XppPrePostArgs args)
{
    str message = Args.getArg('txt');
    str exception = message + con2Str(xSession::xppCallStack());
    
    EventHandlerResult delegateResult = new EventHandlerResult();
            
    SysGlobalTelemetry::instantiateClient(delegateResult);
    if(delegateResult.hasResult() && delegateResult.result() != null)
    {
        if(SysIntParameters::Find().CaptureXppExceptions)
        {
            TelemetryClient cli = delegateResult.result();
            cli.trackException(exception);
        }
    }
}

/// <summary>
/// Log page views to AppInsights
/// </summary>
/// <param name="_formInstance">The arguments for the form run method.</param>
[SubscribesTo(classStr(FormRun), staticDelegateStr(FormRun, onFormRun))]
public static void FormRun_onFormRun(FormRun _formInstance)
{
    EventHandlerResult delegateResult = new EventHandlerResult();
    
    SysGlobalTelemetry::instantiateClient(delegateResult);
    if(delegateResult.hasResult() && delegateResult.result() != null)
    {
        if(SysIntParameters::Find().CaptureFormRun)
        {
            TelemetryClient cli = delegateResult.result();
            if(_formInstance.args() && _formInstance.args().menuItemName())
            {
                cli.trackPageView(_formInstance.args().menuItemName());
            }
        }
    }
}

/// <summary>
/// Logs custom events to AppInsights
/// </summary>
/// <param name = "_eventName">ClassName.MethodName as a strFmt</param>
public static void logEvent(str _eventName)
{
    EventHandlerResult delegateResult = new EventHandlerResult();
    
    SysGlobalTelemetry::instantiateClient(delegateResult);
    if(delegateResult.hasResult() && delegateResult.result() != null)
    {
        if(SysIntParameters::Find().CaptureUserSessions)
        {
            TelemetryClient cli = delegateResult.result();
            cli.trackEvent(_eventName);
        }
    }
}

/// <summary>
/// Logs custom metrics to AppInsights
/// </summary>
/// <param name = "_metricName">Metric Name</param>
/// <param name = "_metricValue">Metric Value as REAL</param>
public static void logMetric(str _metricName, real _metricValue)
{
    EventHandlerResult delegateResult = new EventHandlerResult();
    
    SysGlobalTelemetry::instantiateClient(delegateResult);
    if(delegateResult.hasResult() && delegateResult.result() != null)
    {
        if(SysIntParameters::Find().CaptureCustomMetrics)
        {
            TelemetryClient cli = delegateResult.result();
            cli.trackMetric(_metricName, _metricValue);
        }
    }
}

    /// <summary>
    /// Flushes the telemetry client.
    /// </summary>
    public static void clientFlush()
    {
        EventHandlerResult delegateResult = new EventHandlerResult();

        SysGlobalTelemetry::instantiateClient(delegateResult);
        if(delegateResult.hasResult() && delegateResult.result() != null)
        {
            TelemetryClient cli = delegateResult.result();
            cli.flush();
        }
    }
